#!/bin/sh
# Campaign 3: every tracked configuration generated by the base builder and by
# the head builder, each in its own disposable tree copy; the out/ trees and
# the in-tree files the builder rewrites are compared.
# Usage: c3_byte_identity.sh <base tree> <head tree> <receipt dir>
B=$1; H=$2; R=$3; mkdir -p "$R"
O=$R/c3_out; rm -rf "$O"; mkdir -p "$O"
for side in base head; do
  [ $side = base ] && T=$B || T=$H
  (cd "$T" && for c in $(git ls-files 'configs/endstation_*.yaml'); do
     python3 sw/builder/endstation_builder.py -o "$O/$side" "$c" > "$O/$side.$(basename $c .yaml).log" 2>&1
     echo "$c rc=$?" >> "$O/$side.rc"
   done
   git status --porcelain > "$O/$side.status")
done
(cd "$O/base" && find . -type f | sort | xargs sha256sum) > "$R/c3_base.sha256"
(cd "$O/head" && find . -type f | sort | xargs sha256sum) > "$R/c3_head.sha256"
diff -r "$O/base" "$O/head" > "$R/c3_diff.txt" 2>&1; echo "diff_r_rc=$?" > "$R/c3_summary.txt"
cmp "$R/c3_base.sha256" "$R/c3_head.sha256" >> "$R/c3_summary.txt" 2>&1; echo "sha_list_cmp_rc=$?" >> "$R/c3_summary.txt"
echo "files=$(wc -l < "$R/c3_head.sha256")" >> "$R/c3_summary.txt"
cat "$O/base.rc" "$O/head.rc" >> "$R/c3_summary.txt"
echo "--- base tree status after generation"; cat "$O/base.status" >> "$R/c3_summary.txt"
echo "--- head tree status after generation" >> "$R/c3_summary.txt"; cat "$O/head.status" >> "$R/c3_summary.txt"
echo done > "$R/c3.done"
